package main

import (
	"encoding/json"
	"os"
	"reflect"
	"testing"
)

// Both languages consume this fixture; it is not regenerated by the tests.
func TestSharedVectors(t *testing.T) {
	data, err := os.ReadFile("../native-vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var vectors []struct {
		Request  request
		Expected json.RawMessage
	}
	if err = json.Unmarshal(data, &vectors); err != nil {
		t.Fatal(err)
	}
	for i, v := range vectors {
		result, err := call(v.Request)
		if err != nil {
			t.Fatal(err)
		}
		encoded, err := json.Marshal(result)
		if err != nil {
			t.Fatal(err)
		}
		var actual, expected any
		json.Unmarshal(encoded, &actual)
		json.Unmarshal(v.Expected, &expected)
		if !reflect.DeepEqual(actual, expected) {
			t.Fatalf("vector %d (%s): got %s want %s", i, v.Request.Method, encoded, v.Expected)
		}
	}
}
